//
// choices.js
// Theme module
//

import Choices from 'choices.js';

const toggles = document.querySelectorAll('[data-choices]');

toggles.forEach((toggle) => {
  const elementOptions = toggle.dataset.choices ? JSON.parse(toggle.dataset.choices) : {};

  const defaultOptions = {
    classNames: {
      containerInner: Array.from(toggle.classList),
      input: 'form-control',
      inputCloned: 'form-control-sm',
      listDropdown: 'dropdown-menu',
      itemChoice: 'dropdown-item',
      activeState: 'show',
      selectedState: 'active',
    },
    shouldSort: false,
    callbackOnCreateTemplates: function (template, escapeForTemplate, getClassNames) {
      return {
        choice: ({ classNames, allowHTML }, data) => {
          const classes = [
            ...getClassNames(classNames.item),
            ...getClassNames(classNames.itemChoice),
            ...getClassNames(data.disabled ? classNames.itemDisabled : classNames.itemSelectable),
          ].join(' ');
          const disabled = data.disabled ? 'data-choice-disabled aria-disabled="true"' : 'data-choice-selectable';
          const role = data.group ? 'role="treeitem"' : 'role="option"';
          const selectText = this.config.itemSelectText;
          const text = escapeForTemplate(allowHTML, data.label);

          const label =
            data.customProperties && data.customProperties.avatarSrc
              ? `
            <div class="avatar avatar-xs me-3">
              <img class="avatar-img rounded-circle" src="${data.customProperties.avatarSrc}" alt="${text}" >
            </div> ${text}
          `
              : text;

          return template(`
            <div id="${data.elementId}" class="${classes}" data-select-text="${selectText}" data-choice ${disabled} data-id="${data.id}" data-value="${data.value}" ${role}>
              ${label}
            </div>
          `);
        },
      };
    },
  };

  const options = {
    ...elementOptions,
    ...defaultOptions,
  };

  new Choices(toggle, options);
});

// Make available globally
window.Choices = Choices;
